// ***************
// Filename: frame_counter_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of frame_counter: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to frame_counter's logic on named ports,
//   its status comes back on input ports. Frame counters with interrupts and
//   an event log. Generated by ip/scripts/regmap_gen.py from
//   frame_counter_regs.json: edit the JSON and regenerate (the IP_VERSION /
//   IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "FCNT" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x18 IRQ_EN      RW   interrupt enable per channel, reset 0x0
//     0x1C STATUS      W1C  marker seen per channel (interrupt while
//                       enabled); write 1 to clear, reset 0x0
//     0x20 CLEAR       WO   write 1s: clear COUNT[i]
//     0x24 EVENT       RO   oldest logged event
//                       [31] VALID: an event is logged
//                       [30] OVERFLOW: events lost (log was full)
//                       [26:24] CHANNEL: channel of the marker
//                       [23:0] COUNT: the channel's count after the marker
//     0x28 EVENT_TIME  RO   timestamp of that event (TIME ticks)
//     0x2C EVENT_POP   WO   log control
//                       [0] POP: 1: remove the oldest event
//                       [1] OVF_CLR: 1: clear the overflow flag
//     0x30 + 4 i COUNT [NCH] RO   frames counted by channel i
//     0x50 TIME        RO   timestamp now (ticks of TS_DIV clocks)
//     0x54 EV_EN       RW   channels logged in the event log, reset 0x0
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - clk. Reset
//   - synchronous active low rst_n. Latency - 2 clocks per write and read.
// Date: 2026-10-16
module frame_counter_regs #(
  parameter int NCH = 2  // counters (1..8)
) (
  input  logic                  clk,            // clock
  input  logic                  rst_n,          // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // r: frame_counter_regs_if.regs (src/include/frame_counter_regs_if.sv) {irq_en_o=cfg_irq_en irq_en_wr_o=cfg_irq_en_wr status_o=cfg_status status_wr_o=cfg_status_wr status_set_i=sts_status_set clear_o=cfg_clear clear_wr_o=cfg_clear_wr event_i=sts_event event_time_i=sts_event_time event_pop_o=cfg_event_pop event_pop_wr_o=cfg_event_pop_wr count_i=sts_count time_i=sts_time ev_en_o=cfg_ev_en ev_en_wr_o=cfg_ev_en_wr}
  frame_counter_regs_if.regs r
);
  // register signals, joined to the interface r
  logic [NCH-1:0] irq_en_o;
  logic irq_en_wr_o;
  logic [NCH-1:0] status_o;
  logic status_wr_o;
  logic [NCH-1:0] status_set_i;
  logic [NCH-1:0] clear_o;
  logic clear_wr_o;
  logic [32-1:0] event_i;
  logic [32-1:0] event_time_i;
  logic [2-1:0] event_pop_o;
  logic event_pop_wr_o;
  logic [(NCH)*(32)-1:0] count_i;
  logic [32-1:0] time_i;
  logic [NCH-1:0] ev_en_o;
  logic ev_en_wr_o;
  assign r.cfg_irq_en = irq_en_o;
  assign r.cfg_irq_en_wr = irq_en_wr_o;
  assign r.cfg_status = status_o;
  assign r.cfg_status_wr = status_wr_o;
  assign status_set_i = r.sts_status_set;
  assign r.cfg_clear = clear_o;
  assign r.cfg_clear_wr = clear_wr_o;
  assign event_i = r.sts_event;
  assign event_time_i = r.sts_event_time;
  assign r.cfg_event_pop = event_pop_o;
  assign r.cfg_event_pop_wr = event_pop_wr_o;
  assign count_i = r.sts_count;
  assign time_i = r.sts_time;
  assign r.cfg_ev_en = ev_en_o;
  assign r.cfg_ev_en_wr = ev_en_wr_o;
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "FCNT";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10112026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_IRQ_EN = 8'h18;
  localparam logic [7:0] A_STATUS = 8'h1C;
  localparam logic [7:0] A_CLEAR = 8'h20;
  localparam logic [7:0] A_EVENT = 8'h24;
  localparam logic [7:0] A_EVENT_TIME = 8'h28;
  localparam logic [7:0] A_EVENT_POP = 8'h2C;
  localparam logic [7:0] A_COUNT = 8'h30;   // + 4 i, i < NCH
  localparam logic [7:0] A_TIME = 8'h50;
  localparam logic [7:0] A_EV_EN = 8'h54;
  localparam int MAP_WORDS = 22;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(8)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(clk),
    .aresetn(rst_n),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] irq_en_q;
  logic [31:0] status_q;
  logic [31:0] clear_q;
  logic [31:0] event_pop_q;
  logic [31:0] ev_en_q;
  logic ro_count;   // a write to an element of COUNT
  always_comb begin
    ro_count = 1'b0;
    for (int i = 0; i < NCH; i++) if (wa == A_COUNT + 8'(4 * i)) ro_count = 1'b1;
  end
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      irq_en_q <= 32'h0;
      irq_en_wr_o <= 1'b0;
      status_q <= 32'h0;
      status_wr_o <= 1'b0;
      clear_q <= '0;
      clear_wr_o <= 1'b0;
      event_pop_q <= '0;
      event_pop_wr_o <= 1'b0;
      ev_en_q <= 32'h0;
      ev_en_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_EVENT || wa == A_EVENT_TIME || ro_count || wa == A_TIME);   // writes to read-only words: SLVERR
      begin
        irq_en_wr_o <= wr_en && wa == A_IRQ_EN;
        if (wr_en && wa == A_IRQ_EN) irq_en_q <= (irq_en_q & ~wmask) | (wr_data & wmask);
      end
      begin
        status_wr_o <= wr_en && wa == A_STATUS;
        status_q <= ((wr_en && wa == A_STATUS) ? status_q & ~(wr_data & wmask) : status_q) | 32'(status_set_i);   // a set wins over a clear
      end
      begin
        clear_wr_o <= wr_en && wa == A_CLEAR;
        if (wr_en && wa == A_CLEAR) clear_q <= (clear_q & ~wmask) | (wr_data & wmask);
      end
      begin
        event_pop_wr_o <= wr_en && wa == A_EVENT_POP;
        if (wr_en && wa == A_EVENT_POP) event_pop_q <= (event_pop_q & ~wmask) | (wr_data & wmask);
      end
      begin
        ev_en_wr_o <= wr_en && wa == A_EV_EN;
        if (wr_en && wa == A_EV_EN) ev_en_q <= (ev_en_q & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign irq_en_o = irq_en_q[NCH-1:0];
  assign status_o = status_q[NCH-1:0];
  assign clear_o = clear_q[NCH-1:0];
  assign event_pop_o = event_pop_q[2-1:0];
  assign ev_en_o = ev_en_q[NCH-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge clk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_IRQ_EN: rd_data = irq_en_q;
      A_STATUS: rd_data = status_q;
      A_EVENT: rd_data = 32'(event_i);
      A_EVENT_TIME: rd_data = 32'(event_time_i);
      A_TIME: rd_data = 32'(time_i);
      A_EV_EN: rd_data = ev_en_q;
      default: begin
        for (int i = 0; i < NCH; i++)
          if (rd_addr_q == A_COUNT + 8'(4 * i)) rd_data = 32'(count_i[i*(32) +: 32]);
      end
    endcase
  end
endmodule
